css:
/* ============ Dala · 星图夜幕：纯黑虚空 + 巨幅居中排版 ============ */
body { font-size: 17px; font-weight: 200; line-height: 1.5; overflow-x: hidden; }

/* 氛围：极光压成极低亮度的星雾（紫 + 品牌青 + 微量藏红花） */
.aurora i { filter: blur(120px); }
.aurora i:nth-child(1) { background: #8952ff; opacity: .11; }
.aurora i:nth-child(2) { background: #15846e; opacity: .07; }
.aurora i:nth-child(3) { background: #ffb829; opacity: .045; }

/* ---- 顶栏：透明导航，大写 14px / 600 / 大字距；滚动时回落为纯夜底 ---- */
header { background: transparent; backdrop-filter: none; -webkit-backdrop-filter: none; border-bottom: 0 !important; padding: 26px 48px; }
header.scrolled { background: var(--bg); border-bottom: 1px solid rgba(255, 255, 255, .07) !important; }
.brand h1 { font-weight: 400; font-size: 18px; letter-spacing: -0.01em; }
.brand h1 em { color: var(--accent); }
.brand .sub { color: #9a9a9a; letter-spacing: .3em; text-transform: uppercase; font-weight: 600; }
nav { background: transparent; border: 0; padding: 0; gap: 30px; backdrop-filter: none; }
nav button { font: 600 14px/1.2 var(--font-body); text-transform: uppercase; letter-spacing: .22em; color: #9a9a9a; padding: 6px 0; border-radius: 0; }
nav button:hover { color: #ffffff; }
nav button.active { background: transparent; color: #ffffff; text-shadow: 0 0 18px rgba(137, 82, 255, .6); }
#theme-switch { background: var(--accent); border-color: var(--accent); color: #ffffff; border-radius: 24px; font: 600 12px/1.2 var(--font-body); text-transform: uppercase; letter-spacing: .22em; padding: 12px 20px; }
#theme-switch:hover { border-color: var(--accent); color: #ffffff; filter: brightness(1.1); }
#btn-import { background: transparent; border: 1px solid rgba(255, 255, 255, .16); color: #9a9a9a; border-radius: 24px; font: 600 12px/1.2 var(--font-body); text-transform: uppercase; letter-spacing: .22em; padding: 12px 20px; }
#btn-import:hover { border-color: var(--accent); color: #ffffff; }

/* ---- 单栏中列：全部正文收窄至 900px 居中 ---- */
main { max-width: 900px; }

/* ---- 按钮体系：唯一的紫色 pill CTA；其余一律幽灵文字 ---- */
.btn { border-radius: 24px; font: 600 14px/1.2 var(--font-body); text-transform: uppercase; letter-spacing: .22em; padding: 14.4px 24px; backdrop-filter: none; }
.btn.primary { background: var(--accent); border-color: var(--accent); color: #ffffff; font-weight: 600; }
.btn.primary:hover { box-shadow: none; filter: brightness(1.12); transform: none; }
.btn:not(.primary) { background: transparent; border-color: transparent; color: #ffffff; font-weight: 400; }
.btn:not(.primary):hover { background: transparent; border-color: transparent; color: var(--accent-2); transform: none; }
.btn.ghost { color: #9a9a9a; }
.btn.ghost:hover { color: #ffffff; }

/* ---- 落地页 ---- */
#landing .mark { background: transparent; border: 0; box-shadow: none; color: var(--accent); font-family: var(--font-display); animation: none; text-shadow: 0 0 32px rgba(137, 82, 255, .55); }
#landing h2 { font-weight: 400; font-size: 42px; letter-spacing: -1.68px; }
#landing p { font-weight: 200; font-size: 18px; color: #bdbdbd; }

/* ---- Hero：整屏居中；顶部 100% 宽 × 40vh 的星图夜幕带；巨号标题 ---- */
.hero { display: flex; flex-direction: column; align-items: center; text-align: center; justify-content: center; min-height: calc(100vh - 90px); padding: 0 0 64px; gap: 0; }
.hero .sig { display: block; width: 100vw; max-width: 100vw; height: 40vh; min-height: 260px; margin: 0 calc(50% - 50vw) 34px; }
.hello { justify-content: center; color: var(--accent-2); font-size: 14px; font-weight: 600; letter-spacing: .42em; text-transform: uppercase; margin-bottom: 30px; }
.hello::before { display: none; }
.hero-title { font-weight: 400; font-size: clamp(62px, 8.6vw, 116px); line-height: 1.05; letter-spacing: -0.04em; margin-bottom: 32px; }
.hero-title.long { font-size: clamp(30px, 3.6vw, 48px); letter-spacing: -0.02em; font-weight: 400; line-height: 1.2; }
.hero-title .hl { background: none; -webkit-background-clip: initial; background-clip: initial; color: var(--accent); -webkit-text-fill-color: var(--accent); }
.hero-essence { font-size: 18px; font-weight: 200; color: #bdbdbd; max-width: 560px; margin: 0 auto 34px; }
.hero-essence strong { color: var(--accent-2); font-weight: 400; }
.hero-actions { justify-content: center; margin-top: 8px; }

/* 趋势条：幽灵文字条，数字用琥珀点缀 */
.trend-row { justify-content: center; gap: 30px; margin: 0 0 8px; }
.trend { background: transparent; border: 0; backdrop-filter: none; padding: 0; font-size: 13px; font-weight: 200; color: #9a9a9a; letter-spacing: .12em; }
.trend b { color: var(--accent-2); font-weight: 400; }

/* ---- 星云标签：发光星点 ---- */
.nebula { height: 300px; width: 100%; margin-top: 56px; }
.neb-tag { background: rgba(137, 82, 255, .08); border: 0; backdrop-filter: none; border-radius: 9999px; font-weight: 200; color: #ffffff; box-shadow: 0 0 18px rgba(137, 82, 255, .45), 0 0 3px rgba(137, 82, 255, .8); }
.neb-tag:hover { border-color: transparent; color: var(--accent-2); box-shadow: 0 0 26px rgba(255, 184, 41, .5), 0 0 4px rgba(255, 184, 41, .9); }
.neb-tag b { color: var(--accent-2); font-weight: 400; }

/* ---- 统计：无容器，超轻数字 ---- */
.stat-row { gap: 48px; margin: 64px 0 72px; }
.stat { background: transparent; border: 0; box-shadow: none; backdrop-filter: none; padding: 12px 0; border-radius: 0; text-align: center; }
.stat:hover { border-color: transparent; }
.stat .num { font-weight: 200; font-size: 56px; letter-spacing: -0.03em; }
.stat .label { color: #9a9a9a; text-transform: uppercase; letter-spacing: .3em; font-size: 12px; font-weight: 400; }
.stat .spark { display: none; }

/* ---- 分区标题：Section Headline Block —— 大尺度 weight 400，不要小号大写标签 ---- */
.dash-grid { grid-template-columns: 1fr; gap: 72px; }
.rail { gap: 72px; }
.panel { background: transparent; border: 0; box-shadow: none; backdrop-filter: none; padding: 12px 0; border-radius: 0; }
.panel:hover { border-color: transparent; }
.panel h3 { font-size: 36px; font-weight: 400; letter-spacing: -0.02em; line-height: 1.2; text-transform: none; color: #ffffff; margin-bottom: 28px; display: block; }
.panel h3::after { display: none; }
.persona-md h1, .persona-md h2 { font-weight: 400; font-size: 24px; letter-spacing: -0.48px; color: #ffffff; }
.persona-md p, .persona-md li { font-weight: 200; font-size: 15px; }
.persona-md strong { color: var(--accent-2); font-weight: 400; }
.persona-md blockquote { border-left-color: var(--accent); color: #bdbdbd; font-weight: 200; }

/* ---- 进度 / 列表：扁平紫色，无渐变；发丝线分隔 ---- */
.tag-bar .fill, .progress-fill, .mini-plan .mp-fill { background: var(--accent); }
.tag-bar .track, .progress-track, .mini-plan .mp-bar { background: rgba(255, 255, 255, .08); }
.tag-bar .name { font-weight: 200; }
.material-item, .mini-plan { border-bottom-color: rgba(255, 255, 255, .08); }
.mini-plan .mp-t { font-weight: 400; font-size: 15px; }
.mini-plan:hover .mp-t { color: var(--accent); text-shadow: 0 0 18px rgba(137, 82, 255, .5); }

/* ---- 洞察页：单栏中列；组件全部幽灵化 ---- */
.insight-grid { grid-template-columns: 1fr; gap: 72px; margin-top: 40px; }
.insight-grid .wide { grid-column: auto; }
.fw-wall { grid-template-columns: 1fr; gap: 0; }
.fw-card { background: transparent; border: 0; border-bottom: 1px solid rgba(255, 255, 255, .08); border-radius: 0; padding: 26px 4px; backdrop-filter: none; }
.fw-card:first-child { padding-top: 4px; }
.fw-card:hover { border-color: transparent; border-bottom-color: rgba(137, 82, 255, .5); transform: none; }
.fw-card .fw-name { font-weight: 400; font-size: 24px; letter-spacing: -0.02em; color: #ffffff; }
.fw-card .fw-desc { font-weight: 200; font-size: 15px; color: #bdbdbd; }
.fw-card .fw-links a { color: var(--accent-2); font-size: 11px; text-transform: uppercase; letter-spacing: .2em; }
.bipolar { gap: 30px; }
.bp-row .bp-ends { font-size: 14px; font-weight: 200; color: #9a9a9a; margin-bottom: 12px; }
.bp-row .bp-ends b { font-weight: 400; color: #ffffff; }
.bp-row .bp-ends .bp-val { color: var(--accent-2); font-weight: 400; }
.bp-track { height: 4px; background: rgba(255, 255, 255, .08); }
.bp-fill { background: var(--accent); }
.bp-thumb { width: 12px; height: 12px; background: #ffffff; box-shadow: 0 0 14px var(--accent), 0 0 4px var(--accent); }
.red-list, .gap-list { gap: 12px; }
.red-item { background: transparent; border-left: 2px solid #e05a4e; border-radius: 0; padding: 10px 18px; font-size: 15px; font-weight: 200; color: #ffffff; }
.gap-item { background: transparent; border-left: 2px solid var(--accent-2); border-radius: 0; padding: 10px 18px; font-size: 15px; font-weight: 200; color: #bdbdbd; }
.corr-item { border-bottom-color: rgba(255, 255, 255, .08); font-weight: 200; font-size: 15px; padding: 12px 0; }
.corr-item .c-no { color: var(--accent); letter-spacing: .2em; }
.heatmap { gap: 4px; }
.hm-col { gap: 4px; }
.hm-cell { width: 11px; height: 11px; border-radius: 50%; background: rgba(255, 255, 255, .07); }
.hm-cell.l1 { background: rgba(137, 82, 255, .3); }
.hm-cell.l2 { background: rgba(137, 82, 255, .55); }
.hm-cell.l3 { background: rgba(137, 82, 255, .8); }
.hm-cell.l4 { background: var(--accent); box-shadow: 0 0 8px rgba(137, 82, 255, .7); }
.hm-legend { letter-spacing: .1em; }
.insight-empty { font-weight: 200; color: #7a7a7a; }

/* ---- 知识卡片：幽灵式单栏长列表，发丝线，hover 微光 ---- */
.card-grid { grid-template-columns: 1fr; gap: 0; }
#cards-grid { grid-template-columns: 1fr !important; gap: 0 !important; }
.chip { background: transparent; border: 0; color: #9a9a9a; text-transform: uppercase; letter-spacing: .2em; font-size: 12px; font-weight: 600; border-radius: 9999px; backdrop-filter: none; }
.chip:hover { color: #ffffff; transform: none; }
.chip.active { background: transparent; color: var(--accent); text-shadow: 0 0 16px rgba(137, 82, 255, .55); }
.search-box { background: transparent; border-color: rgba(255, 255, 255, .14); border-radius: 9999px; backdrop-filter: none; font-weight: 200; }
.search-box:focus { border-color: var(--accent); box-shadow: 0 0 20px rgba(137, 82, 255, .25); }
.kcard { background: transparent; border: 0; box-shadow: none; backdrop-filter: none; padding: 30px 4px 26px; border-radius: 0; border-bottom: 1px solid rgba(255, 255, 255, .08); gap: 10px; }
.kcard:hover { border-color: transparent; border-bottom-color: rgba(137, 82, 255, .5); }
.kcard:hover .ctitle { text-shadow: 0 0 24px rgba(137, 82, 255, .6); }
.kcard .ctitle { font-weight: 400; font-size: 27px; letter-spacing: -0.02em; line-height: 1.3; order: 2; transition: text-shadow .25s; }
.kcard .cmeta { order: 1; font-size: 12px; font-weight: 400; text-transform: uppercase; letter-spacing: .2em; color: var(--accent); }
.kcard .csummary { order: 3; font-weight: 200; font-size: 15px; color: #bdbdbd; }
.kcard .ctags { order: 4; }
.mini-tag { background: transparent; color: #9a9a9a; border-radius: 9999px; font-weight: 400; letter-spacing: .2em; text-transform: uppercase; font-size: 11px; padding: 3px 0; margin-right: 14px; }
.mini-tag::before { content: "✦ "; color: var(--accent); }

/* ---- 规划卡：幽灵化对齐 ---- */
.plan-list { gap: 0; margin-top: 36px; }
.plan-card { background: transparent; border: 0; box-shadow: none; backdrop-filter: none; padding: 36px 0; border-radius: 0; border-bottom: 1px solid rgba(255, 255, 255, .08); }
.plan-card:first-child { padding-top: 12px; }
.plan-card:hover { border-color: transparent; border-bottom-color: rgba(137, 82, 255, .5); }
.plan-head .ptitle { font-weight: 400; font-size: 27px; letter-spacing: -0.02em; }
.status-badge { background: transparent; border: 0; padding: 4px 0; text-transform: uppercase; letter-spacing: .2em; font-size: 11px; font-weight: 600; color: #9a9a9a; border-radius: 0; }
.status-badge.active { color: var(--accent-2); background: transparent; text-shadow: 0 0 14px rgba(255, 184, 41, .45); }
.plan-meta { color: #7a7a7a; font-weight: 200; }
.plan-goal { font-weight: 200; font-size: 15px; color: #bdbdbd; margin-top: 10px; }
.plan-basis { border-top: 0; font-weight: 200; }
.task { border-bottom-color: rgba(255, 255, 255, .08); font-weight: 200; }
.task input[type="checkbox"] { border-radius: 50%; border-color: #9a9a9a; background: transparent; }
.task input[type="checkbox"]:checked { background: var(--accent); border-color: var(--accent); box-shadow: 0 0 12px rgba(137, 82, 255, .55); }
.task input[type="checkbox"]:checked::after { color: #ffffff; }

/* ---- 图谱 / 时间线 ---- */
#graph-box { background: transparent; border: 1px solid rgba(255, 255, 255, .08); border-radius: 24px; box-shadow: none; backdrop-filter: none; }
.tl::before { background: rgba(255, 255, 255, .1); }
.tl-month::before { background: var(--accent); box-shadow: 0 0 14px var(--accent), 0 0 3px var(--accent); }
.tl-month .mname { font-weight: 400; font-size: 24px; letter-spacing: -0.02em; }
.tl-item { background: transparent; border: 0; box-shadow: none; backdrop-filter: none; border-bottom: 1px solid rgba(255, 255, 255, .08); border-radius: 0; padding: 18px 4px; }
.tl-item:hover { transform: none; border-bottom-color: rgba(137, 82, 255, .5); }
.tl-item:hover .t { text-shadow: 0 0 20px rgba(137, 82, 255, .55); }
.tl-item .t { font-weight: 400; font-size: 18px; transition: text-shadow .25s; }
.tl-item .d { font-weight: 200; }

/* ---- 弹窗：虚空中的黑盒，发丝描边，无阴影 ---- */
#modal-mask { background: rgba(0, 0, 0, .82); }
#modal { background: var(--bg); border: 1px solid rgba(255, 255, 255, .14); border-radius: 24px; box-shadow: none; }
#modal h2 { font-weight: 400; font-size: 36px; letter-spacing: -0.02em; line-height: 1.2; }
#modal .mmeta { font-size: 12px; text-transform: uppercase; letter-spacing: .2em; color: #9a9a9a; }
#modal .mmeta a { color: var(--accent-2); }
#modal .mbody { border-top-color: rgba(255, 255, 255, .1); }
.mbody h2 { font-size: 14px !important; color: var(--accent-2) !important; font-weight: 600 !important; text-transform: uppercase; }
.mbody p, .mbody li { font-weight: 200; }
#modal .edit-area { background: var(--bg); border-color: rgba(255, 255, 255, .14); border-radius: 12px; }
#modal .close-x { color: #9a9a9a; font-weight: 200; }
#modal .close-x:hover { color: #ffffff; }
#toast { background: var(--bg); box-shadow: none; border-radius: 9999px; border-color: var(--accent); }
#status-bar { background: rgba(5, 2, 10, .88); border-top-color: rgba(255, 255, 255, .08); letter-spacing: .12em; }

/* ---- 拖拽导入遮罩 ---- */
#drop-mask { background: rgba(5, 2, 10, .86); backdrop-filter: blur(6px); }
#drop-mask .drop-inner { border: 1.5px dashed var(--accent); border-radius: 24px; box-shadow: inset 0 0 60px rgba(137, 82, 255, .18); }
#drop-mask b { font-weight: 400; font-size: 27px; letter-spacing: -0.02em; }

/* ---- 动效：克制，仅保留柔和浮现 ---- */
.reveal { transform: translateY(14px); }

@media (max-width: 960px) {
  .hero { min-height: auto; justify-content: flex-start; padding: 24px 0 48px; }
  .hero .sig { height: 28vh; min-height: 200px; margin-bottom: 22px; }
  .hero-title { font-size: clamp(42px, 11vw, 62px); }
  .panel h3 { font-size: 27px; }
  nav { gap: 16px; }
  .stat-row { gap: 20px; }
  .stat .num { font-size: 40px; }
}
